"""
Call Script Schema Definitions with Driving Agents
Implements state machine for voice calls with agent-driven nodes using Pydantic
Supports default agents at script level with node-level overrides
"""

from datetime import datetime
from enum import Enum
from typing import Any, Optional

from pydantic import BaseModel, Field, field_validator, model_validator


class NodeColor(str, Enum):
    """Node resolution colors following traffic light pattern"""

    GREEN = "green"  # Happy path - successful outcome
    YELLOW = "yellow"  # Alternative path - conditional branch
    RED = "red"  # Error path - system failure or rejection


class AgentType(str, Enum):
    """Types of driving agents for nodes"""

    GREETING = "greeting"  # Initial contact and introduction
    QUALIFIER = "qualifier"  # Qualification questions
    INFORMATION = "information"  # Information gathering
    CONFIRMATION = "confirmation"  # Confirm details
    CLOSER = "closer"  # Close the call/deal


class RequirementLevel(str, Enum):
    """Data collection requirement levels"""

    MANDATORY = "mandatory"  # Must collect to proceed
    PREFERRED = "preferred"  # Should collect if possible
    OPTIONAL = "optional"  # Nice to have


class BranchingResolveStrategy(str, Enum):
    """Strategies for resolving branching conditions"""

    MOVE_FORWARD = "move-forward"  # Proceed to next node
    RETURN_TO_GREEN = "return-to-green"  # Go back to the original node with yellow path and proceed to its green path


class JobPositionContext(BaseModel):
    """Context about the job position being discussed"""

    title: str
    description: str | None = None
    company: str
    client: str | None = None
    location: str | None = None
    pay_range: dict[str, float] = Field(default_factory=dict)  # min/max
    pay_currency: str = "USD"  # Default currency
    contract_type: str | None = None  # W2, 1099, etc
    duration: str | None = None
    start_date: str | None = None  # Expected start date
    schedule: str | None = None
    requirements: list[str] = Field(default_factory=list)  # Required skills/qualifications
    benefits: list[str] = Field(default_factory=list)
    metadata: dict[str, Any] = Field(default_factory=dict)

    @field_validator("pay_range")
    @classmethod
    def validate_pay_range(cls, v: dict[str, float]) -> dict[str, float]:
        if v and "min" in v and "max" in v:
            if v["min"] > v["max"]:
                raise ValueError("Minimum pay cannot be greater than maximum pay")
        return v


class VoiceProfile(BaseModel):
    """Voice characteristics for agents"""

    voice_id: str
    name: str
    language: str = "en-US"
    pitch: float = Field(default=1.0, ge=0.5, le=2.0)
    speed: float = Field(default=1.0, ge=0.5, le=2.0)
    emotion: str | None = None
    personality_traits: list[str] = Field(default_factory=list)


class DrivingAgentConfig(BaseModel):
    """Agent responsible for resolving a node"""

    agent_type: AgentType
    name: str
    description: str
    instructions: str | None = None
    voice_profile_id: str | None = None
    personality_traits: list[str] = Field(default_factory=list)
    capabilities: list[str] = Field(default_factory=list)
    tools: list[str] = Field(default_factory=list)  # Available tool calls

    def merge_with_defaults(self, default_agent: Optional["DrivingAgentConfig"]) -> "DrivingAgentConfig":
        """Merge this agent with default agent settings"""
        if not default_agent or default_agent.agent_type != self.agent_type:
            return self

        # Create a merged agent, with node-level settings taking precedence
        merged_data = default_agent.model_dump()
        node_data = self.model_dump(exclude_unset=True)

        # Merge lists (combine unique values)
        for list_field in ["personality_traits", "capabilities", "tools"]:
            if list_field in node_data:
                merged_data[list_field] = list(set(merged_data.get(list_field, []) + node_data[list_field]))

        # Override other fields
        for key, value in node_data.items():
            if key not in ["personality_traits", "capabilities", "tools"]:
                merged_data[key] = value

        return DrivingAgentConfig(
            agent_type=merged_data.get("agent_type", self.agent_type),
            name=merged_data.get("name", self.name),
            description=merged_data.get("description", self.description),
            **merged_data,
        )


class AgentOverride(BaseModel):
    """Partial agent definition for node-level overrides"""

    agent_type: AgentType | None = None
    name: str | None = None
    description: str | None = None
    instructions: str | None = None
    voice_profile_id: str | None = None
    personality_traits: list[str] | None = None
    capabilities: list[str] | None = None
    tools: list[str] | None = None

    def to_driving_agent(self, default_agent: DrivingAgentConfig) -> DrivingAgentConfig:
        """Convert override to full DrivingAgentConfig using defaults"""
        # Start with default agent data
        agent_data = default_agent.model_dump()

        # Apply overrides
        override_data = self.model_dump(exclude_unset=True)

        # For lists, we can choose to replace or extend
        for list_field in ["personality_traits", "capabilities", "tools"]:
            if list_field in override_data and override_data[list_field] is not None:
                # Replace the list entirely with override
                agent_data[list_field] = override_data[list_field]

        # Override other fields
        for key, value in override_data.items():
            if key not in ["personality_traits", "capabilities", "tools"] and value is not None:
                agent_data[key] = value

        return DrivingAgentConfig(**agent_data)


class SuccessStrategy(BaseModel):
    """Defines output path for a specific color"""

    color: NodeColor = Field(default=NodeColor.GREEN)
    target_node_id: str
    description: str | None = None


class BranchingStrategy(BaseModel):
    """Defines output path for a specific color"""

    color: NodeColor = Field(default=NodeColor.YELLOW)
    target_node_id: str
    condition: str | None = None  # Condition for YELLOW paths
    description: str | None = None
    on_resolve: BranchingResolveStrategy = BranchingResolveStrategy.RETURN_TO_GREEN


class ExceptionStrategy(BaseModel):
    """Defines output path for a specific color"""

    color: NodeColor = Field(default=NodeColor.RED)
    target_node_id: str | None = None  # Can be None to end call


class CallNodeMetadata(BaseModel):
    """Metadata for call nodes"""

    should_record_response: bool = True
    max_retries: int = Field(default=2, ge=0, le=10)
    timeout_seconds: int = Field(default=30, ge=5, le=300)


class CallNode(BaseModel):
    """Node in the call script state machine"""

    id: str
    title: str
    initiationText: str | None = None
    prompt: str | None = None

    # Agent configuration - can be full agent or override
    driving_agent: DrivingAgentConfig | None = None  # Full agent definition
    agent_override: AgentOverride | None = None  # Partial override of default
    agent_type: AgentType  # Just specify which default agent to use

    # Output strategies (following constraints)
    green_path: SuccessStrategy | None = None  # Exactly 1 for non-terminal
    yellow_paths: list[BranchingStrategy] = Field(default_factory=list)  # 0 to many
    red_path: ExceptionStrategy | None = None  # Exactly 1 for non-terminal

    # Node configuration
    requirement_level: RequirementLevel = RequirementLevel.OPTIONAL
    is_terminal: bool = False

    # Data collection
    data_points: list[str] = Field(default_factory=list)  # Data to collect
    required_context: list[str] = Field(default_factory=list)  # Required from previous

    # Metadata
    metadata: CallNodeMetadata = Field(default_factory=CallNodeMetadata)
    tags: list[str] = Field(default_factory=list)

    @model_validator(mode="after")
    def validate_paths(self) -> "CallNode":
        """Validate node path constraints"""
        if not self.is_terminal:
            # Non-terminal nodes must have exactly 1 green path
            if not self.green_path:
                raise ValueError(f"Node {self.id}: Non-terminal node must have exactly 1 green path")

            # Non-terminal nodes must have exactly 1 red path
            if not self.red_path:
                raise ValueError(f"Node {self.id}: Non-terminal node must have exactly 1 red path")
        else:
            # Terminal nodes should not have any paths
            if self.green_path or self.yellow_paths or self.red_path:
                raise ValueError(f"Node {self.id}: Terminal node should not have output paths")

        # Validate yellow paths have conditions
        for yellow_path in self.yellow_paths:
            if not yellow_path.condition:
                raise ValueError(f"Node {self.id}: Yellow path to {yellow_path.target_node_id} must have a condition")

        return self

    @model_validator(mode="after")
    def validate_agent_config(self) -> "CallNode":
        """Validate that node has some form of agent configuration"""
        # Must have agent_type at minimum
        if not self.agent_type:
            raise ValueError(f"Node {self.id}: Must have agent_type")

        # Can't have both full agent and override
        if self.driving_agent and self.agent_override:
            raise ValueError(f"Node {self.id}: Cannot have both driving_agent and agent_override")

        return self

    def get_resolved_agent(self, default_agents: dict[AgentType, DrivingAgentConfig]) -> DrivingAgentConfig:
        """Get the resolved agent for this node using defaults if needed"""
        # If node has a full agent definition, use it
        if self.driving_agent:
            return self.driving_agent

        # If node has an override, apply it to the default
        if self.agent_override:
            # Determine which default agent to use
            agent_type = self.agent_override.agent_type or self.agent_type
            if not agent_type:
                raise ValueError(f"Node {self.id}: agent_override must specify agent_type")

            default_agent = default_agents.get(agent_type)
            if not default_agent:
                raise ValueError(f"Node {self.id}: No default agent for type {agent_type}")

            return self.agent_override.to_driving_agent(default_agent)

        # If node just specifies agent type, use the default
        if self.agent_type:
            default_agent = default_agents.get(self.agent_type)
            if not default_agent:
                raise ValueError(f"Node {self.id}: No default agent for type {self.agent_type}")
            return default_agent

        raise ValueError(f"Node {self.id}: Unable to resolve agent configuration")

    def enrich_with_context(self, context: dict[str, Any]) -> "CallNode":
        """Format the node's prompt with provided context"""
        # Create a copy of the current node
        node_data = self.model_dump()

        # Format initiationText if it exists
        if node_data.get("initiationText"):
            node_data["initiationText"] = self._format_text_with_context(node_data["initiationText"], context)

        # Format prompt if it exists
        if node_data.get("prompt"):
            node_data["prompt"] = self._format_text_with_context(node_data["prompt"], context)

        # Return a new CallNode instance with the formatted text
        return CallNode(**node_data)

    def _format_text_with_context(self, text: str, context: dict[str, Any]) -> str:
        """Format prompt with context variables"""
        formatted = text
        for key, value in context.items():
            placeholder = f"{{{key}}}"
            if placeholder in formatted:
                formatted = formatted.replace(placeholder, str(value))
        return formatted


class NodeResolution(BaseModel):
    """Result of node resolution by driving agent"""

    node_id: str
    color: NodeColor
    next_node_id: str | None = None
    suggested_action: str | None = None  # For YELLOW paths
    extracted_data: dict[str, Any] = Field(default_factory=dict)
    confidence: float = Field(default=1.0, ge=0.0, le=1.0)
    timestamp: datetime = Field(default_factory=datetime.now)


class DefaultAgents(BaseModel):
    """Default agent configurations for the script"""

    greeting: DrivingAgentConfig | None = None
    qualifier: DrivingAgentConfig | None = None
    information: DrivingAgentConfig | None = None
    confirmation: DrivingAgentConfig | None = None
    closer: DrivingAgentConfig | None = None

    def get_agent(self, agent_type: AgentType) -> DrivingAgentConfig | None:
        """Get default agent by type"""
        return getattr(self, agent_type.value, None)

    def to_dict(self) -> dict[AgentType, DrivingAgentConfig]:
        """Convert to dictionary keyed by AgentType"""
        result = {}
        for agent_type in AgentType:
            agent = self.get_agent(agent_type)
            if agent:
                result[agent_type] = agent
        return result


class CallScript(BaseModel):
    """Complete call script definition"""

    # Metadata
    id: str
    name: str
    version: str
    description: str

    # Job context
    job_context: JobPositionContext

    # Default agents for the script
    default_agents: DefaultAgents = Field(default_factory=DefaultAgents)

    # Script structure
    nodes: list[CallNode]
    start_node_id: str

    # Voice profiles
    voice_profiles: dict[str, VoiceProfile]
    default_voice_profile_id: str

    # Call configuration
    call_config: dict[str, Any] = Field(default_factory=dict)
    global_timeout_seconds: int = Field(default=1800, ge=60, le=7200)
    max_conversation_turns: int = Field(default=100, ge=1, le=500)

    # Initial context
    initial_context: dict[str, Any] = Field(default_factory=dict)

    # Metadata
    created_at: str = ""
    updated_at: str = ""
    tags: list[str] = Field(default_factory=list)
    metadata: dict[str, Any] = Field(default_factory=dict)

    @field_validator("start_node_id")
    @classmethod
    def validate_start_node(cls, v: str, info) -> str:
        """Validate start node exists"""
        if "nodes" in info.data:
            node_ids = {node.id for node in info.data["nodes"]}
            if v not in node_ids:
                raise ValueError(f"Start node '{v}' not found in nodes")
        return v

    @field_validator("default_voice_profile_id")
    @classmethod
    def validate_default_voice(cls, v: str, info) -> str:
        """Validate default voice profile exists"""
        if "voice_profiles" in info.data:
            if v not in info.data["voice_profiles"]:
                raise ValueError(f"Default voice profile '{v}' not found")
        return v

    def get_node(self, node_id: str) -> CallNode | None:
        """Get node by ID"""
        for node in self.nodes:
            if node.id == node_id:
                return node
        return None

    def get_node_agent(self, node_id: str) -> DrivingAgentConfig | None:
        """Get the resolved agent for a specific node"""
        node = self.get_node(node_id)
        if not node:
            return None

        return node.get_resolved_agent(self.default_agents.to_dict())

    def validate_structure(self) -> list[str]:
        """Validate the entire call script structure"""
        errors = []

        # Check all node references exist
        node_ids = {node.id for node in self.nodes}
        default_agents_dict = self.default_agents.to_dict()

        for node in self.nodes:
            # Validate node can resolve its agent
            try:
                agent = node.get_resolved_agent(default_agents_dict)

                # Check voice profile reference if specified
                if agent.voice_profile_id:
                    if agent.voice_profile_id not in self.voice_profiles:
                        errors.append(
                            f"Node '{node.id}' agent references non-existent voice profile '{agent.voice_profile_id}'"
                        )
            except ValueError as e:
                errors.append(str(e))

            if not node.is_terminal:
                # Check green path target
                if node.green_path and node.green_path.target_node_id not in node_ids:
                    errors.append(
                        f"Node '{node.id}' green path targets non-existent node '{node.green_path.target_node_id}'"
                    )

                # Check yellow path targets
                for yellow_path in node.yellow_paths:
                    if yellow_path.target_node_id not in node_ids:
                        errors.append(
                            f"Node '{node.id}' yellow path targets non-existent node '{yellow_path.target_node_id}'"
                        )

                # Check red path target
                if node.red_path and node.red_path.target_node_id not in node_ids:
                    errors.append(
                        f"Node '{node.id}' red path targets non-existent node '{node.red_path.target_node_id}'"
                    )

        # Check for orphaned nodes
        reachable = self._find_reachable_nodes()
        orphaned = node_ids - reachable
        if orphaned:
            errors.append(f"Orphaned nodes found: {orphaned}")

        return errors

    def _find_reachable_nodes(self) -> set[str]:
        """Find all reachable nodes from start"""
        start_node = self.get_node(self.start_node_id)
        if not start_node:
            return set()

        visited = set()
        to_visit = [self.start_node_id]

        while to_visit:
            current_id = to_visit.pop()
            if current_id in visited:
                continue

            visited.add(current_id)
            current_node = self.get_node(current_id)

            if current_node and not current_node.is_terminal:
                # Add all possible next nodes
                if current_node.green_path:
                    to_visit.append(current_node.green_path.target_node_id)

                for yellow_path in current_node.yellow_paths:
                    to_visit.append(yellow_path.target_node_id)

                if current_node.red_path:
                    to_visit.append(
                        current_node.red_path.target_node_id
                    ) if current_node.red_path.target_node_id else None

        return visited

    class Config:
        """Pydantic config"""

        use_enum_values = True
        json_encoders = {datetime: lambda v: v.isoformat()}

    def model_dump_json(self, indent: int | None = None, **kwargs) -> str:
        """Override to ensure proper JSON serialization"""
        # Handle indent separately since it's not a parameter of model_dump_json
        if indent is not None:
            # Use model_dump to get the dictionary, then json.dumps with indent
            import json

            data = self.model_dump(**kwargs)
            return json.dumps(data, indent=indent, default=str)
        else:
            # Use Pydantic's built-in JSON serialization
            return super().model_dump_json(**kwargs)

    @classmethod
    def from_camel_case(cls, data: dict) -> "CallScript":
        """Create CallScript from camelCase JSON data"""
        converted = cls._convert_from_camel_case(data)
        return cls.model_validate(converted)

    @classmethod
    def _convert_from_camel_case(cls, data: dict) -> dict:
        """Convert camelCase JSON to snake_case for Pydantic"""
        # Field mapping for common conversions
        field_mapping = {
            "jobContext": "job_context",
            "voiceProfiles": "voice_profiles",
            "defaultVoiceProfileId": "default_voice_profile_id",
            "startNodeId": "start_node_id",
            "dataSchema": "data_schema",
            "requiredData": "required_data",
            "callConfig": "call_config",
            "globalTimeoutSeconds": "global_timeout_seconds",
            "maxConversationTurns": "max_conversation_turns",
            "initialContext": "initial_context",
            "createdAt": "created_at",
            "updatedAt": "updated_at",
            "drivingAgent": "driving_agent",
            "agentType": "agent_type",
            "voiceProfileId": "voice_profile_id",
            "personalityTraits": "personality_traits",
            "defaultAgents": "default_agents",
            "agentOverride": "agent_override",
            "outputStrategies": "output_strategies",
            "greenPath": "green_path",
            "yellowPaths": "yellow_paths",
            "redPath": "red_path",
            "targetNodeId": "target_node_id",
            "requirementLevel": "requirement_level",
            "maxRetries": "max_retries",
            "timeoutSeconds": "timeout_seconds",
            "isTerminal": "is_terminal",
            "dataPoints": "data_points",
            "requiredContext": "required_context",
            "shouldRecordResponse": "should_record_response",
            "followPromptStrictly": "follow_prompt_strictly",
            "payRange": "pay_range",
            "contractType": "contract_type",
            "voiceId": "voice_id",
            # Note: initiationText stays as is since that's the field name in the schema
            "onResolve": "on_resolve",
        }

        def convert_dict(d: dict) -> dict:
            """Recursively convert dictionary keys"""
            if not isinstance(d, dict):
                return d

            result = {}
            for key, value in d.items():
                new_key = field_mapping.get(key, key)

                if isinstance(value, dict):
                    result[new_key] = convert_dict(value)
                elif isinstance(value, list):
                    result[new_key] = [convert_dict(item) if isinstance(item, dict) else item for item in value]
                else:
                    result[new_key] = value

            return result

        # Handle nodes with output strategies
        if "nodes" in data:
            converted_nodes = []
            for node in data["nodes"]:
                converted_node = convert_dict(node)

                # Handle output strategies
                if "outputStrategies" in node or "output_strategies" in node:
                    strategies = node.get("outputStrategies", node.get("output_strategies", {}))

                    if strategies.get("green"):
                        converted_node["green_path"] = convert_dict(strategies["green"])

                    if strategies.get("yellow"):
                        converted_node["yellow_paths"] = [convert_dict(path) for path in strategies["yellow"]]

                    if strategies.get("red"):
                        converted_node["red_path"] = convert_dict(strategies["red"])

                    converted_node.pop("outputStrategies", None)
                    converted_node.pop("output_strategies", None)

                converted_nodes.append(converted_node)

            data["nodes"] = converted_nodes

        return convert_dict(data)

